import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { UseMutationResult, UseQueryResult } from "@tanstack/react-query";
import { useDataProvider } from "./provider";
import type {
    CreateResponse,
    UpdateResponse,
    DeleteOneResponse,
    GetOneResponse,
    HttpError
} from "./types";

export const useOne = <
    TData = any,
    TError = HttpError
>(params: {
    resource: string;
    id: any;
    meta?: any;
    queryOptions?: any;
}): UseQueryResult<GetOneResponse<TData>, TError> => {
    const dataProvider = useDataProvider();

    return useQuery<GetOneResponse<TData>, TError>({
        queryKey: [params.resource, "detail", params.id, params.meta],
        queryFn: () => dataProvider.getOne<TData>({
            resource: params.resource,
            id: params.id,
            meta: params.meta,
        }),
        ...params.queryOptions,
    });
};

export const useCreate = <
    TData = any,
    TError = HttpError,
    TVariables = any
>(): UseMutationResult<
    CreateResponse<TData>,
    TError,
    { resource?: string; variables: TVariables; meta?: any },
    unknown
> => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();

    return useMutation<CreateResponse<TData>, TError, { resource?: string; variables: TVariables; meta?: any }>({
        mutationFn: ({ resource, variables, meta }) => {
            return dataProvider.create<TData, TVariables>({
                resource: resource || "",
                variables,
                meta,
            });
        },
        onSuccess: (_data, variables) => {
            if (variables.resource) {
                queryClient.invalidateQueries({ queryKey: [variables.resource] });
            }
        },
    });
};

export const useUpdate = <
    TData = any,
    TError = HttpError,
    TVariables = any
>(): UseMutationResult<
    UpdateResponse<TData>,
    TError,
    { resource: string; id: any; variables: TVariables; meta?: any },
    unknown
> => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();

    return useMutation<UpdateResponse<TData>, TError, {
        resource: string;
        id: any;
        variables: TVariables;
        meta?: any;
    }>({
        mutationFn: ({ resource, id, variables, meta }) => {
            return dataProvider.update<TData, TVariables>({
                resource,
                id,
                variables,
                meta,
            });
        },
        onSuccess: (_data, { resource, id }) => {
            queryClient.invalidateQueries({ queryKey: [resource, "list"] });
            queryClient.invalidateQueries({ queryKey: [resource, "detail", id] });
        },
    });
};

export const useDelete = <
    TData = any,
    TError = HttpError
>(): UseMutationResult<
    DeleteOneResponse<TData>,
    TError,
    { resource: string; id: any; meta?: any },
    unknown
> => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();

    return useMutation<DeleteOneResponse<TData>, TError, {
        resource: string;
        id: any;
        meta?: any;
    }>({
        mutationFn: ({ resource, id, meta }) => {
            return dataProvider.deleteOne<TData>({
                resource,
                id,
                meta,
            });
        },
        onSuccess: (_data, { resource }) => {
            queryClient.invalidateQueries({ queryKey: [resource, "list"] });
        },
    });
};

import { createContext, useContext } from "react";
import type { 
    GetListResponse, 
    GetManyResponse, 
    GetOneResponse, 
    CrudFilter, 
    CrudSort, 
    Pagination,
    CreateResponse,
    UpdateResponse,
    DeleteOneResponse
} from "./types";

export interface DataProvider {
    getList: <TData = any>(params: {
        resource: string;
        pagination?: Pagination;
        filters?: CrudFilter[];
        sorters?: CrudSort[];
        meta?: any;
    }) => Promise<GetListResponse<TData>>;

    getMany: <TData = any>(params: {
        resource: string;
        ids: any[];
        meta?: any;
    }) => Promise<GetManyResponse<TData>>;

    getOne: <TData = any>(params: {
        resource: string;
        id: any;
        meta?: any;
    }) => Promise<GetOneResponse<TData>>;

    create: <TData = any, TVariables = any>(params: {
        resource: string;
        variables: TVariables;
        meta?: any;
    }) => Promise<CreateResponse<TData>>;

    update: <TData = any, TVariables = any>(params: {
        resource: string;
        id: any;
        variables: TVariables;
        meta?: any;
    }) => Promise<UpdateResponse<TData>>;

    deleteOne: <TData = any>(params: {
        resource: string;
        id: any;
        meta?: any;
    }) => Promise<DeleteOneResponse<TData>>;

    custom: <TData = any>(params: {
        url: string;
        method: "get" | "post" | "put" | "patch" | "delete";
        filters?: CrudFilter[];
        sorters?: CrudSort[];
        payload?: any;
        query?: any;
        headers?: any;
        meta?: any;
    }) => Promise<TData>;
}

export const createDataProvider = (apiUrl: string): DataProvider => ({
    getList: async ({ resource, pagination, filters, sorters }) => {
        const url = new URL(`${apiUrl}/${resource}`);
        
        if (pagination) {
            url.searchParams.append("_start", String(((pagination.current || 1) - 1) * (pagination.pageSize || 10)));
            url.searchParams.append("_end", String((pagination.current || 1) * (pagination.pageSize || 10)));
        }

        if (sorters && sorters.length > 0) {
            url.searchParams.append("_sort", sorters[0].field);
            url.searchParams.append("_order", sorters[0].order);
        }

        if (filters) {
            filters.forEach(filter => {
                const operator = filter.operator || "eq";
                const { field, value } = filter;

                switch (operator) {
                    case "eq":
                        url.searchParams.append(field, value);
                        break;
                    case "ne":
                        url.searchParams.append(`${field}_ne`, value);
                        break;
                    case "lt":
                        url.searchParams.append(`${field}_lt`, value);
                        break;
                    case "gt":
                        url.searchParams.append(`${field}_gt`, value);
                        break;
                    case "lte":
                        url.searchParams.append(`${field}_lte`, value);
                        break;
                    case "gte":
                        url.searchParams.append(`${field}_gte`, value);
                        break;
                    case "contains":
                        url.searchParams.append(`${field}_like`, value);
                        break;
                    // Add more mappings as needed based on your backend API
                    default:
                         url.searchParams.append(field, value);
                }
            });
        }

        const response = await fetch(url.toString());
        if (!response.ok) throw new Error(response.statusText);
        
        const data = await response.json();
        const total = Number(response.headers.get("x-total-count"));

        return {
            data,
            total: total || data.length,
        };
    },

    getMany: async ({ resource, ids }) => {
        const url = new URL(`${apiUrl}/${resource}`);
        ids.forEach(id => url.searchParams.append("id", id));
        
        const response = await fetch(url.toString());
        if (!response.ok) throw new Error(response.statusText);
        
        const data = await response.json();
        return { data };
    },

    getOne: async ({ resource, id }) => {
        const response = await fetch(`${apiUrl}/${resource}/${id}`);
        if (!response.ok) throw new Error(response.statusText);
        
        const data = await response.json();
        return { data };
    },

    create: async ({ resource, variables }) => {
        const response = await fetch(`${apiUrl}/${resource}`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify(variables),
        });

        if (!response.ok) throw new Error(response.statusText);

        const data = await response.json();
        return { data };
    },

    update: async ({ resource, id, variables }) => {
        const response = await fetch(`${apiUrl}/${resource}/${id}`, {
            method: "PATCH",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify(variables),
        });

        if (!response.ok) throw new Error(response.statusText);

        const data = await response.json();
        return { data };
    },

    deleteOne: async ({ resource, id }) => {
        const response = await fetch(`${apiUrl}/${resource}/${id}`, {
            method: "DELETE",
        });

        if (!response.ok) throw new Error(response.statusText);

        const data = await response.json();
        return { data };
    },

    custom: async ({ url, method, payload, query, headers }) => {
        let requestUrl = new URL(url.startsWith("http") ? url : `${apiUrl}${url}`);
        
        if (query) {
            Object.keys(query).forEach(key => {
                requestUrl.searchParams.append(key, query[key]);
            });
        }

        const response = await fetch(requestUrl.toString(), {
            method,
            headers: {
                "Content-Type": "application/json",
                ...headers,
            },
            body: payload ? JSON.stringify(payload) : undefined,
        });

        if (!response.ok) throw new Error(response.statusText);
        return await response.json();
    }
});

export const defaultDataProvider = createDataProvider("https://api.fake-rest.refine.dev");

const DataProviderContext = createContext<DataProvider | undefined>(undefined);

export const DataProviderProvider = DataProviderContext.Provider;

export const useDataProvider = () => {
    const context = useContext(DataProviderContext);
    return context || defaultDataProvider;
};

import { createContext, useContext, useMemo } from "react";
export interface AuthProvider {
  login: (params: any) => Promise<any>;
  logout: (params: any) => Promise<any>;
  check: (params?: any) => Promise<any>;
  onError: (error: any) => Promise<any>;
  getPermissions?: (params?: any) => Promise<any>;
  getIdentity?: (params?: any) => Promise<any>;
  register?: (params: any) => Promise<any>;
  forgotPassword?: (params: any) => Promise<any>;
  updatePassword?: (params: any) => Promise<any>;
  [key: string]: any;
}

const AuthContext = createContext<AuthProvider | undefined>(undefined);

export const AuthProviderProvider = AuthContext.Provider;

export const useAuthProvider = () => {
  return useContext(AuthContext);
};

export const useLogin = () => {
  const provider = useAuthProvider();

  const mutate = async (params: any) => {
    if (!provider) throw new Error("No AuthProvider found.");
    return await provider.login(params);
  };

  return { mutate };
};

export const useLogout = () => {
  const provider = useAuthProvider();

  const mutate = async (params: any) => {
    if (!provider) throw new Error("No AuthProvider found.");
    return await provider.logout(params);
  };

  return { mutate };
};

export const useRegister = () => {
  const provider = useAuthProvider();

  const mutate = async (params: any) => {
    if (!provider?.register)
      throw new Error("Register method not implemented in AuthProvider.");
    return await provider.register(params);
  };

  return { mutate };
};

export const useIsAuthenticated = () => {
  const provider = useAuthProvider();

  const check = async (params?: any) => {
    if (!provider) return false;
    try {
      await provider.check(params);
      return true;
    } catch (error) {
      return false;
    }
  };

  return { check };
};

export const useGetIdentity = () => {
  const provider = useAuthProvider();

  const getIdentity = async (params?: any) => {
    if (!provider?.getIdentity) return undefined;
    return await provider.getIdentity(params);
  };

  return { getIdentity };
};

export const usePermissions = () => {
  const provider = useAuthProvider();

  const getPermissions = async (params?: any) => {
    if (!provider?.getPermissions) return undefined;
    return await provider.getPermissions(params);
  };

  return { getPermissions };
};

