export const createAuthProvider = (authUrl: string): AuthProvider => ({
  login: async ({ email }) => {
    // Example: POST to your auth endpoint
    // const response = await fetch(`${authUrl}/login`, { method: "POST", body: ... });

    if (email) {
      localStorage.setItem("my_access_token", email);
      return { success: true };
    }
    return { success: false, error: "Invalid credentials" };
  },
  logout: async () => {
    localStorage.removeItem("my_access_token");
    return { success: true };
  },
  check: async () => {
    const token = localStorage.getItem("my_access_token");
    if (token) return { authenticated: true };
    throw new Error("Not authenticated");
  },
  getPermissions: async () => ["admin"],
  getIdentity: async () => {
    const token = localStorage.getItem("my_access_token");
    // Example: Fetch identity from authUrl
    // const response = await fetch(`${authUrl}/me`, ...);

    return {
      id: 1,
      name: "Jane Doe",
      avatar: "https://i.pravatar.cc/150?u=a042581f4e29026704d",
      email: token,
    };
  },
  onError: async (error) => {
    console.error(error);
    return { error };
  },
});

export const defaultAuthProvider = createAuthProvider("");

import { useNavigate, useSearch, useLocation } from "@tanstack/react-router";

export const useGo = () => {
  const navigate = useNavigate();

  return ({
    to,
    query,
    type = "push",
  }: {
    to?: string;
    query?: any;
    type?: "push" | "replace";
  }) => {
    navigate({
      to,
      search: query,
      replace: type === "replace",
    });
  };
};

export const useParsed = () => {
    const search = useSearch({ strict: false });
    const location = useLocation();

    return {
        id: (search as any).id,
        resource: location.pathname.split("/")[1], // Simple heuristic
        action: location.pathname.split("/").pop(), // Simple heuristic
        pathname: location.pathname,
        params: search,
    }
}

export const useBack = () => {
    const navigate = useNavigate();
    return () => navigate({ to: ".." });
}

export type BaseKey = string | number;

export interface BaseRecord {
    id?: BaseKey;
    [key: string]: any;
}

export interface MetaQuery {
    [key: string]: any;
}

export interface Pagination {
    current?: number;
    pageSize?: number;
    mode?: "client" | "server";
}

export interface HttpError {
    message: string;
    statusCode: number;
    [key: string]: any;
}

export interface GetListResponse<TData = BaseRecord> {
    data: TData[];
    total: number;
    [key: string]: any;
}

export interface GetManyResponse<TData = BaseRecord> {
    data: TData[];
    [key: string]: any;
}

export interface GetOneResponse<TData = BaseRecord> {
    data: TData;
    [key: string]: any;
}

export interface CreateResponse<TData = BaseRecord> {
    data: TData;
    [key: string]: any;
}

export interface UpdateResponse<TData = BaseRecord> {
    data: TData;
    [key: string]: any;
}

export interface DeleteOneResponse<TData = BaseRecord> {
    data: TData;
    [key: string]: any;
}

export type CrudOperators =
  | "eq"
  | "ne"
  | "lt"
  | "gt"
  | "lte"
  | "gte"
  | "in"
  | "nin"
  | "contains"
  | "ncontains"
  | "containss"
  | "ncontainss"
  | "between"
  | "nbetween"
  | "null"
  | "nnull"
  | "startswith"
  | "nstartswith"
  | "endswith"
  | "nendswith"
  | "or"
  | "and";

export type CrudFilter = {
    field: string;
    operator?: CrudOperators;
    value: any;
};

export type CrudSort = {
    field: string;
    order: "asc" | "desc";
};

import {
  useQuery,
  type UseQueryOptions,
  type UseQueryResult,
} from "@tanstack/react-query";
import { useDataProvider } from "./provider";
import type { HttpError } from "./types";

interface UseCustomProps<TData = any, TError = HttpError> {
  url: string;
  method: "get" | "post" | "put" | "patch" | "delete";
  config?: {
    filters?: any[];
    sorters?: any[];
    payload?: any;
    query?: any;
    headers?: any;
  };
  queryOptions?: Omit<UseQueryOptions<TData, TError>, "queryKey" | "queryFn">;
  meta?: any;
}

export const useCustom = <TData extends unknown = any, TError = HttpError>({
  url,
  method,
  config,
  queryOptions,
  meta,
}: UseCustomProps<TData, TError>): UseQueryResult<TData, TError> => {
  const dataProvider = useDataProvider();

  return useQuery<TData, TError>({
    queryKey: [url, method, config, meta],
    queryFn: () =>
      dataProvider.custom<TData>({
        url,
        method,
        ...config,
        meta,
      }),
    ...queryOptions,
  });
};

import {
  type InfiniteData,
  useInfiniteQuery,
  type UseInfiniteQueryOptions,
  type UseInfiniteQueryResult,
} from "@tanstack/react-query";
import { useDataProvider } from "./provider";
import type {
  GetListResponse,
  HttpError,
  Pagination,
  CrudFilter,
  CrudSort,
} from "./types";

interface UseInfiniteListProps<TData = any, TError = HttpError> {
  resource: string;
  pagination?: Pagination;
  filters?: CrudFilter[];
  sorters?: CrudSort[];
  queryOptions?: Omit<
    UseInfiniteQueryOptions<
      GetListResponse<TData>,
      TError,
      InfiniteData<GetListResponse<TData>>,
      any,
      number
    >,
    "queryKey" | "queryFn" | "getNextPageParam" | "initialPageParam"
  >;
  meta?: any;
}

export const useInfiniteList = <
  TData extends unknown = any,
  TError = HttpError,
>({
  resource,
  pagination,
  filters,
  sorters,
  queryOptions,
  meta,
}: UseInfiniteListProps<TData, TError>): UseInfiniteQueryResult<
  InfiniteData<GetListResponse<TData>>,
  TError
> => {
  const dataProvider = useDataProvider();

  return useInfiniteQuery<
    GetListResponse<TData>,
    TError,
    InfiniteData<GetListResponse<TData>>,
    any,
    number
  >({
    queryKey: [
      resource,
      "list",
      "infinite",
      pagination,
      filters,
      sorters,
      meta,
    ],
    initialPageParam: 1,
    queryFn: async ({ pageParam = 1 }) => {
      return dataProvider.getList<TData>({
        resource,
        pagination: { ...pagination, current: pageParam as number },
        filters,
        sorters,
        meta,
      });
    },
    getNextPageParam: (lastPage, allPages) => {
      const totalPages = Math.ceil(
        (lastPage.total || 0) / (pagination?.pageSize || 10),
      );
      const currentPage = allPages.length;
      return currentPage < totalPages ? currentPage + 1 : undefined;
    },
    ...queryOptions,
  });
};

import {
  useQuery,
  type UseQueryOptions,
  type UseQueryResult,
} from "@tanstack/react-query";
import { useDataProvider } from "./provider";
import type { GetManyResponse, HttpError, BaseKey } from "./types";

interface UseManyProps<TData = any, TError = HttpError> {
  resource: string;
  ids: BaseKey[];
  queryOptions?: Omit<
    UseQueryOptions<GetManyResponse<TData>, TError>,
    "queryKey" | "queryFn"
  >;
  meta?: any;
}

export const useMany = <TData extends unknown = any, TError = HttpError>({
  resource,
  ids,
  queryOptions,
  meta,
}: UseManyProps<TData, TError>): UseQueryResult<
  GetManyResponse<TData>,
  TError
> => {
  const dataProvider = useDataProvider();

  return useQuery<GetManyResponse<TData>, TError>({
    queryKey: [resource, "getMany", ids, meta],
    queryFn: () =>
      dataProvider.getMany<TData>({
        resource,
        ids,
        meta,
      }),
    enabled: ids.length > 0 && (queryOptions?.enabled ?? true),
    ...queryOptions,
  });
};

import { useSearch, useNavigate } from "@tanstack/react-router";
import { useInfiniteList } from "./useInfiniteList";
import type { CrudFilter, CrudSort, Pagination, HttpError } from "./types";
import type {
  UseInfiniteQueryOptions,
  InfiniteData,
  UseInfiniteQueryResult,
} from "@tanstack/react-query";
import type { GetListResponse } from "./types";

export interface UseTableProps<TData = any, TError = HttpError> {
  resource: string;
  pagination?: Pagination;
  filters?: CrudFilter[];
  sorters?: CrudSort[];
  meta?: any;
  queryOptions?: Omit<
    UseInfiniteQueryOptions<
      GetListResponse<TData>,
      TError,
      InfiniteData<GetListResponse<TData>>,
      any,
      number
    >,
    "queryKey" | "queryFn" | "getNextPageParam" | "initialPageParam"
  >;
}

export type UseTableReturnType<
  TData = any,
  TError = HttpError,
> = UseInfiniteQueryResult<InfiniteData<GetListResponse<TData>>, TError> & {
  tableState: {
    current: number;
    pageSize: number;
  };
  setPagination: (newCurrent: number, newPageSize?: number) => void;
};

export const useTable = <TData extends unknown = any, TError = HttpError>({
  resource,
  pagination: initialPagination,
  filters: initialFilters,
  sorters: initialSorters,
  meta,
  queryOptions,
}: UseTableProps<TData, TError>): UseTableReturnType<TData, TError> => {
  const search = useSearch({ strict: false });
  const navigate = useNavigate();

  const current = (search as any).current
    ? Number((search as any).current)
    : initialPagination?.current || 1;
  const pageSize = (search as any).pageSize
    ? Number((search as any).pageSize)
    : initialPagination?.pageSize || 10;

  const listQuery = useInfiniteList<TData, TError>({
    resource,
    pagination: {
      current,
      pageSize,
    },
    filters: initialFilters,
    sorters: initialSorters,
    meta,
    queryOptions,
  });
  const setPagination = (newCurrent: number, newPageSize?: number) => {
    navigate({
      to: ".",
      search: (prev: any) => ({
        ...prev,
        current: newCurrent,
        pageSize: newPageSize || pageSize,
      }),
      replace: true,
    });
  };

  return {
    ...listQuery,
    tableState: {
      current,
      pageSize,
    },
    setPagination,
  };
};
